// QTP-10FC New Entry Pause Guard — Supabase context v4.2.1
// Blocks ONLY new opening entries. Never blocks exits, stops, trailing stops, or closing orders.
// QTP_PAUSE_GUARD_INTENT_PARSE_FIX_v1_20260526
//   Fix: substring-match on 'CLOSE'/'STOP'/'EXIT' was flagging descriptive OR-clause intents
//   like "sell_short_or_close_per_downstream_state" as closing actions, mis-routing every
//   Broad Scanner new-entry signal to Alpaca Position Closer (→ STAND ASIDE / no fill).
//   Now: exact set match OR end-anchored token match, with explicit OR-clause exclusion.
const closingActions = new Set([
  'SELL_TO_CLOSE', 'BUY_TO_COVER', 'CLOSE', 'EXIT', 'STOP', 'TRAILING_STOP',
  'PROTECTIVE_STOP', 'PROTECTION', 'SCALE_OUT', 'REDUCE_ONLY'
]);
// QTP_PAUSE_GUARD_INTENT_PARSE_FIX_v1_20260526 — descriptive OR-clause exclusion
const _PG_OR_CLAUSE_RE = /_OR_(CLOSE|STOP|EXIT)(_|$)/;
// QTP_PAUSE_GUARD_INTENT_PARSE_FIX_v1_20260526 — end-anchored closing token (suffix or exact)
const _PG_CLOSING_TOKEN_RE = /(^|_)(CLOSE|STOP|EXIT)$/;
function isClosingOrProtective(j) {
  const fields = [j.action, j.order_action, j._order_action, j.intent, j.order_intent, j._intent, j.route, j.order_class]
    .map(v => String(v || '').toUpperCase());
  const hit = fields.some(v => {
    if (!v) return false;
    if (_PG_OR_CLAUSE_RE.test(v)) return false;       // explicit allow for descriptive OR-clauses
    if (closingActions.has(v)) return true;            // exact set membership
    if (_PG_CLOSING_TOKEN_RE.test(v)) return true;     // end-anchored token (..._CLOSE / ..._STOP / ..._EXIT)
    return false;
  });
  if (hit) return true;
  if (j.reduce_only === true || j._reduce_only === true) return true;
  if (j.is_protective === true || j._is_protective === true) return true;
  return false;
}
// QTP_SHORT_SIDE_HALT_v1_gov219_20260814 — PO-authorized after the 07-15 cohort review.
//   Short side since 2026-07-15: 25 closed trades, 2 winners, -$2,279.73, dollar PF 0.2802.
//   Since the 2026-07-23 universe collapse: 10 trades, ZERO winners, -$1,874.03. The long
//   side over that same window: +$482.85, PF 1.290. The ratified -$2,500 cumulative stop was
//   breached at -$3,064.22 and the shorts are essentially all of it.
//   Q5's revert trigger named the LONG side because its window still reaches back past the
//   collapse to SHW (-$453.81 — an overnight gap through a 2.10% stop, exit_reason=manual);
//   ex-SHW the long book is PF 1.24. So the leg halted here is the leg that lost the money.
//   FAIL-SAFE: shorts are blocked unless QTP_SHORT_ENTRIES_ENABLED is explicitly 'true'.
//   Missing, unreadable or malformed => blocked. Capital protection never depends on a value
//   being present. Re-enable from n8n Variables; no deploy needed.
//   EXITS ARE NEVER BLOCKED: this runs AFTER isClosingOrProtective(), so covers, closes,
//   stops and trailing stops on existing short positions bypass it exactly as they did before
//   — the same assumption the gov-213 pause block has already run on in production.
const _QTP_SHORT_TOKEN_RE = /^(SELL|SHORT|BEARISH|SELL_SHORT)$/;
function shortEntriesEnabled() {
  try {
    return typeof $vars !== 'undefined' && $vars !== null &&
           String($vars.QTP_SHORT_ENTRIES_ENABLED).trim().toLowerCase() === 'true';
  } catch (e) { return false; }
}
function isNewShortEntry(j) {
  // Deliberately does NOT read order_intent: the Broad Scanner's descriptive
  // "sell_short_or_close_per_downstream_state" is exactly the OR-clause the 2026-05-26 parse
  // fix exists to keep out of side detection.
  const fields = [j.side, j.execution, j.signal, j.direction, j.signal_direction, j.action, j.order_action]
    .map(v => String(v || '').trim().toUpperCase());
  return fields.some(v => v && _QTP_SHORT_TOKEN_RE.test(v));
}
// Supabase pause control is attached by Format Supabase Pause Guard Context.

return items.map(item => {
  const j = item.json || {};
  const pause = j._supabase_pause_control || {};
  const pauseActive = String(pause.pause_new_entries).toLowerCase() === 'true';

  // QTP_EXEC_FLOW_V2_RISK_OBSERVABILITY_20260506 — observability only, no logic/routing change.
  j._risk_gate_observability = {
    version: 'QTP_EXEC_FLOW_V2_20260506',
    observed_at: new Date().toISOString(),
    ticker: j.ticker || j.symbol || j.Ticker || j.Symbol || null,
    execution: j.execution || j.side || j.direction || j.signal_direction || null,
    legacy_live_vc_score: Number(j.live_vc_score ?? 0),
    live_vc_score_v2: Number(j.live_vc_score_v2 ?? 0),
    vc_threshold_locked: 7,
    vc_v2_passed: Number(j.live_vc_score_v2 ?? 0) >= 7,
    vc_legacy_passed: Number(j.live_vc_score ?? 0) >= 7,
    parity_delta: Number(j._vc_parity_delta ?? 0),
    risk_gate_logic_changed: false,
    alpaca_routing_changed: false,
    protective_exit_logic_changed: false,
    pause_guard_intent_parse_fix_v: 'QTP_PAUSE_GUARD_INTENT_PARSE_FIX_v1_20260526'
  };

  if (isClosingOrProtective(j)) {
    return { json: { ...j, _pause_guard_checked: true, _pause_guard_action: 'BYPASS_PROTECTIVE_OR_CLOSING', _pause_guard_live_order_allowed: true, _pause_guard_fix_v: 'QTP_PAUSE_GUARD_INTENT_PARSE_FIX_v1_20260526' } };
  }
  if (isNewShortEntry(j) && !shortEntriesEnabled()) {
    return { json: { ...j, _pause_guard_checked: true, _pause_guard_action: 'BLOCK_SHORT_ENTRY_ONLY', _pause_guard_live_order_allowed: false, _pause_guard_reason: 'gov 219 short-side halt: 25 closed shorts since 07-15, 2 winners, -$2,279.73, PF 0.2802; 0 winners in 10 since the 07-23 universe collapse. Set QTP_SHORT_ENTRIES_ENABLED=true to re-enable.', _sm_action: 'KILLED', _sm_route: 'SKIP', _sm_reason: 'Short entries halted by gov 219 (short-side PF 0.2802)', _short_halt_v: 'QTP_SHORT_SIDE_HALT_v1_gov219_20260814' } };
  }
  if (pauseActive) {
    return { json: { ...j, _pause_guard_checked: true, _pause_guard_action: 'BLOCK_NEW_ENTRY_ONLY', _pause_guard_live_order_allowed: false, _pause_guard_reason: pause.reason || 'pause_new_entries=true', _sm_action: 'KILLED', _sm_route: 'SKIP', _sm_reason: `New entry paused by QTP-10FC: ${pause.reason || 'pause_new_entries=true'}`, _pause_guard_fix_v: 'QTP_PAUSE_GUARD_INTENT_PARSE_FIX_v1_20260526' } };
  }
  return { json: { ...j, _pause_guard_checked: true, _pause_guard_action: 'ALLOW_NEW_ENTRY', _pause_guard_live_order_allowed: true, _pause_guard_fix_v: 'QTP_PAUSE_GUARD_INTENT_PARSE_FIX_v1_20260526' } };
});

// QTP Supabase Main Trading pause guard query v4.2.1
const d = $json || {};
return [{
  json: {
    ...d,
    __supabase_pause_sql: `
      WITH ctrl AS (
        SELECT pause_new_entries, reason, status, checked_at, expires_at
        FROM quantum.entry_pause_control
        WHERE expires_at > CURRENT_TIMESTAMP
        ORDER BY checked_at DESC
        LIMIT 1
      )
      SELECT
        COALESCE((SELECT pause_new_entries FROM ctrl), false) AS pause_new_entries,
        COALESCE((SELECT reason FROM ctrl), 'no active pause control') AS reason,
        COALESCE((SELECT status FROM ctrl), 'NO_ACTIVE_PAUSE') AS status,
        (SELECT checked_at::text FROM ctrl) AS checked_at,
        (SELECT expires_at::text FROM ctrl) AS expires_at
    `,
    migration_version: 'QTP_SUPABASE_MAIN_TRADING_v4.2.1'
  }
}];

// QTP Supabase Main Trading pause guard context formatter v4.2.1
const original = $('Prepare Supabase Pause Guard Query').first().json || {};
const row = ($input.first() && $input.first().json) || {};
return [{ json: { ...original, _supabase_pause_control: row, _pause_guard_source: 'supabase.entry_pause_control' } }];
